-- compliance_rule -------------------------------------------
CREATE TABLE IF NOT EXISTS compliance_rule (
	id VARCHAR(40) NOT NULL, 
	region VARCHAR(64) NOT NULL, 
	ruleset_version VARCHAR(64) NOT NULL, 
	verified_on DATE, 
	source TEXT, 
	min_setback_front_ft FLOAT NOT NULL, 
	min_setback_rear_ft FLOAT NOT NULL, 
	min_setback_side_ft FLOAT NOT NULL, 
	max_fsi FLOAT NOT NULL, 
	max_ground_coverage FLOAT NOT NULL, 
	max_height_ft FLOAT NOT NULL, 
	min_parking_per_unit INTEGER NOT NULL, 
	required_nocs JSON NOT NULL, 
	PRIMARY KEY (id)
);

